package com.zpantry.media.domain;import com.zpantry.common.persistence.BaseEntity;import jakarta.persistence.*;import java.util.UUID;@Entity@Table(name="media_assets")public class MediaAssetEntity extends BaseEntity{@Column(name="recipe_id")public UUID recipeId;@Column(name="ingredient_id")public UUID ingredientId;@Column(name="public_id")public String publicId;public String url;@Column(name="secure_url")public String secureUrl;@Column(name="resource_type")public String resourceType;public String format;public Integer width;public Integer height;protected MediaAssetEntity(){}public MediaAssetEntity(UUID r,UUID i,String p,String u,String s,String rt,String f,Integer w,Integer h){recipeId=r;ingredientId=i;publicId=p;url=u;secureUrl=s;resourceType=rt;format=f;width=w;height=h;}}
